const APP_VERSION='0.19.0',DB_NAME='VCB_DB_0190',STORE='medicamentos';let db,allMeds=[],selectedLab='',currentCategoryTab='especialidades';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function norm(s){return(s??'').toString().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim()}function esc(s){return(s??'').toString().replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}function toast(m){let t=$('#toast');t.textContent=m;t.style.display='block';clearTimeout(window.__tt);window.__tt=setTimeout(()=>t.style.display='none',2500)}
function openDB(){return new Promise((res,rej)=>{let r=indexedDB.open(DB_NAME,1);r.onupgradeneeded=()=>{let d=r.result;if(!d.objectStoreNames.contains(STORE))d.createObjectStore(STORE,{keyPath:'id'})};r.onsuccess=()=>{db=r.result;res()};r.onerror=()=>rej(r.error)})}function putMany(rows){return new Promise((res,rej)=>{let tx=db.transaction(STORE,'readwrite'),st=tx.objectStore(STORE);rows.forEach(x=>st.put(x));tx.oncomplete=res;tx.onerror=()=>rej(tx.error)})}function getAll(){return new Promise((res,rej)=>{let r=db.transaction(STORE,'readonly').objectStore(STORE).getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function isRegulatoryExcludedMed(x){let comps=principles(x).map(c=>norm(c));return(window.VCB_REGULATORY_EXCLUSIONS||[]).some(r=>(r.principios||[]).some(p=>comps.includes(norm(p))))}function isBoliviaVerifiedMed(x){if(isRegulatoryExcludedMed(x))return false;if(x?.bolivia_verificado===true)return true;let s=norm(x?.fuente||'');return s.includes('lafar.net/')||s.includes('terbol.kokoinc.com/')||s.includes('terbol.com/')}function boliviaMeds(rows){return(rows||[]).filter(isBoliviaVerifiedMed)}function regulatoryQueryNotice(q){let nq=norm(q),html='';let r=(window.VCB_REGULATORY_EXCLUSIONS||[]).find(x=>(x.aliases||[]).some(a=>norm(a)===nq));if(r)html+=`<div class="warning-banner"><b>${esc(r.estado)}:</b> ${esc(r.motivo)} <span class="rule-source">Fuente: ${esc(r.fuente)}</span></div>`;let aa=(window.VCB_REGULATORY_ALERTS||[]).filter(x=>(x.aliases||[]).some(a=>norm(a)===nq)||(x.principios||[]).some(a=>norm(a)===nq));if(aa.length)html+=aa.map(a=>`<div class="warning-banner"><b>${esc(a.estado)}:</b> ${esc(a.motivo)} <span class="rule-source">Fuente: ${esc(a.fuente)}</span></div>`).join('');return html}function medicineRegulatoryAlerts(x){let ps=principles(x).map(norm);let aa=(window.VCB_REGULATORY_ALERTS||[]).filter(a=>(a.principios||[]).some(p=>ps.includes(norm(p))));return aa.map(a=>`<div class="warning-banner"><b>${esc(a.estado)}:</b> ${esc(a.motivo)} <span class="rule-source">Fuente: ${esc(a.fuente)}</span></div>`).join('')}function boliviaSupplies(){return(window.VCB_SUPPLIES||[]).filter(x=>x.verificacion_bolivia===true&&x.visible_publico_bolivia!==false)}function boliviaProviders(){return(window.VCB_SUPPLIES||[]).filter(x=>x.tipo_registro==='proveedor'&&x.visible_publico_bolivia!==false&&(x.verificacion_bolivia===true||x.directorio_visible===true))}function boliviaSupplyProducts(){return boliviaSupplies().filter(x=>x.tipo_registro!=='proveedor')}function boliviaImplants(){return boliviaSupplyProducts().filter(x=>x.grupo_catalogo==='implante'||x.tipo_registro==='implante')}function boliviaServices(){return boliviaSupplyProducts().filter(x=>x.grupo_catalogo==='servicio'||x.tipo_registro==='servicio')}function boliviaNonImplantSupplies(){return boliviaSupplyProducts().filter(x=>!(x.grupo_catalogo==='implante'||x.tipo_registro==='implante'||x.grupo_catalogo==='servicio'||x.tipo_registro==='servicio'))}async function initData(){await openDB();await putMany(window.VCB_SEED||[]);allMeds=boliviaMeds(await getAll());sortCatalog();buildLists();renderFrequent();search();updateSyncUi('Catálogo Bolivia verificado: '+allMeds.length+' medicamentos · '+boliviaImplants().length+' implantes · '+boliviaNonImplantSupplies().length+' insumos/equipos · '+boliviaServices().length+' soporte/alquiler · '+boliviaProviders().length+' proveedores.');setTimeout(()=>maybeSyncCatalog().catch(console.warn),300)}function sortCatalog(){allMeds.sort((a,b)=>norm(a.marca||a.dci).localeCompare(norm(b.marca||b.dci),'es'))}
function evidenceLabelMedicine(x){let e=norm(x?.nivel_evidencia||'');if(e.includes('registro_sanitario'))return'Registro sanitario Bolivia';if(e.includes('catalogo_farmaceutico_bolivia'))return'Catálogo farmacéutico Bolivia';if(e.includes('catalogo_oficial'))return'Catálogo oficial fabricante/importador';if(e.includes('referencia_no_bolivia'))return'Referencia general · no confirma disponibilidad Bolivia';let u=norm(x?.fuente||'');if(u.includes('agemed'))return'Fuente regulatoria AGEMED';if(u.includes('medicamentos.bo'))return'Catálogo farmacéutico Bolivia';return x?.bolivia_verificado===true?'Evidencia Bolivia verificada':'Detalle en verificación'}function evidenceLabelSupply(x){let e=norm(x?.nivel_evidencia||'');if(e.includes('registro_sanitario_bolivia'))return'Registro sanitario de dispositivo Bolivia';if(e.includes('directorio_local_mas_antecedente'))return'Directorio local + antecedente público';if(e.includes('servicio_alquiler_confirmado'))return'Servicio de alquiler publicado por proveedor Bolivia';if(e.includes('servicio_columna_confirmado_alif_pendiente'))return'Soporte de columna confirmado · ALIF específico pendiente';if(e.includes('aporte_usuario_pendiente'))return'Proveedor reportado · verificación documental pendiente';if(e.includes('catalogo_proveedor_bolivia'))return'Producto publicado por proveedor Bolivia · DI pendiente';if(e.includes('catalogo_oficial_distribuidor_bolivia'))return'Catálogo oficial del distribuidor Bolivia';if(e.includes('directorio_local'))return'Directorio local · cotejo AGEMED pendiente';return x?.registro_sanitario?'Registro sanitario publicado':'Fuente Bolivia verificada'}function safeSourceLink(url){try{let u=new URL(url);if(!['http:','https:'].includes(u.protocol))return'';return`<a class="source-link" href="${esc(u.href)}" target="_blank" rel="noopener">Abrir fuente</a>`}catch{return url?`<span class="rule-source">${esc(url)}</span>`:''}}function evidenceBlockMedicine(x){let reg=x.registro?`<div><b>Registro:</b> ${esc(x.registro)}</div>`:'';let src=x.fuente?`<div><b>Fuente:</b> ${safeSourceLink(x.fuente)}</div>`:'';let date=x.fecha_fuente?`<div><b>Revisado:</b> ${esc(x.fecha_fuente)}</div>`:'';return`<div class="modal-section"><h4>Verificación Bolivia</h4><div class="verification-note"><b>${esc(evidenceLabelMedicine(x))}</b>${reg}${date}${src}<div>Estado AGEMED: ${esc(x.cotejo_agemed||'pendiente de conciliación individual')}</div></div></div>`}function evidenceBlockSupply(x){let reg=x.registro_sanitario?`<div><b>Registro sanitario:</b> ${esc(x.registro_sanitario)}</div>`:'';let src=x.fuente_bolivia?`<div><b>Fuente Bolivia:</b> ${safeSourceLink(x.fuente_bolivia)}</div>`:'';let src2=x.fuente&&x.fuente!==x.fuente_bolivia?`<div><b>Fuente fabricante/producto:</b> ${safeSourceLink(x.fuente)}</div>`:'';let date=x.fecha_verificacion_bolivia?`<div><b>Revisado:</b> ${esc(x.fecha_verificacion_bolivia)}</div>`:'';let ag=x.validacion_agemed?`<div><b>Conciliación AGEMED:</b> ${esc(x.validacion_agemed)}</div>`:'';let ant=x.antecedente_regulatorio_bolivia?`<div class="reg-history"><b>Antecedente regulatorio:</b> ${esc(x.antecedente_regulatorio_bolivia)}${x.fuente_regulatoria_historica?` · ${safeSourceLink(x.fuente_regulatoria_historica)}`:''}</div>`:'';let mod=x.modalidad_comercial?`<div><b>Modalidad comercial:</b> ${esc(x.modalidad_comercial)}</div>`:'';let rent=x.modalidad_alquiler?`<div><b>Alquiler/consignación:</b> ${esc(x.modalidad_alquiler)}</div>`:'';let alif=x.nota_alif?`<div><b>ALIF:</b> ${esc(x.nota_alif)}</div>`:'';return`<div class="modal-section"><h4>Nivel de evidencia</h4><div class="verification-note"><b>${esc(evidenceLabelSupply(x))}</b>${reg}${date}${src}${src2}${ag}${ant}${mod}${rent}${alif}</div></div>`}
function principles(x){return(x.principios&&x.principios.length?x.principios:[x.dci]).filter(Boolean)}function isCombined(x){return principles(x).length>1||/[+;]/.test(x.dci||'')}
function searchable(x){let s=norm([x.marca,x.dci,x.laboratorio,principles(x).join(' '),(x.presentaciones||[]).join(' '),(x.aliases||[]).join(' '),x.accion_terapeutica||''].join(' '));if(/valproato|acido valproico/.test(s))s+=' acido valproico valproato de sodio';if(/paracetamol|acetaminofen/.test(s))s+=' paracetamol acetaminofen';if(/metamizol|dipirona/.test(s))s+=' metamizol dipirona';if(/diclofenaco/.test(s))s+=' diclofenaco';if(/laiden/.test(s))s+=' layden';return s}
function supplierRegionalText(x){return(x.contactos_departamento||[]).flatMap(c=>[c.departamento,c.ciudad,(c.telefonos||[]).join(' '),c.whatsapp||'',c.direccion||'']).join(' ')}function supplySearchable(x){return norm([x.marca,x.nombre,x.fabricante,x.categoria,x.proveedor_bolivia,(x.telefonos||[]).join(' '),(x.presentaciones||[]).join(' '),(x.aliases||[]).join(' '),(x.familias||[]).join(' '),supplierRegionalText(x),x.implant_family||'',x.grupo_catalogo||''].join(' '))}
function wordTokens(s){return norm(s).split(/[^a-z0-9]+/).filter(Boolean)}
function medSearchFields(x){let f=[x.marca,x.dci,...principles(x),...(x.aliases||[]),x.laboratorio,...(x.presentaciones||[])].filter(Boolean);let s=searchable(x);if(/valproato|acido valproico/.test(s))f.push('acido valproico','valproato de sodio');if(/paracetamol|acetaminofen/.test(s))f.push('paracetamol','acetaminofen');if(/metamizol|dipirona/.test(s))f.push('metamizol','dipirona');if(/laiden/.test(s))f.push('layden');return f}
function prefixQueryMatch(fields,q){let qt=wordTokens(q);if(!qt.length)return false;let fw=fields.flatMap(wordTokens);return qt.every(t=>fw.some(w=>w===t||w.startsWith(t)))}
function fieldRank(field,q){let n=norm(field),nq=norm(q);if(!n)return 0;if(n===nq)return 1200;if(n.startsWith(nq))return 1000;let ws=wordTokens(n),qt=wordTokens(nq);if(qt.length&&qt.every(t=>ws.some(w=>w===t)))return 900;if(qt.length&&qt.every(t=>ws.some(w=>w.startsWith(t))))return 700;return 0}
function searchScore(x,q){let fields=medSearchFields(x);if(!prefixQueryMatch(fields,q))return 0;let primary=[x.marca,x.dci,...principles(x),...(x.aliases||[])].filter(Boolean),secondary=[x.laboratorio,...(x.presentaciones||[])].filter(Boolean);return Math.max(1,...primary.map(f=>fieldRank(f,q)),...secondary.map(f=>Math.floor(fieldRank(f,q)/2)))}
function supplySearchScore(x,q){let regional=(x.contactos_departamento||[]).flatMap(c=>[c.departamento,c.ciudad,...(c.telefonos||[]),c.whatsapp,c.direccion]);let fields=[x.marca,x.nombre,x.fabricante,x.categoria,x.proveedor_bolivia,...(x.telefonos||[]),...(x.presentaciones||[]),...(x.aliases||[]),...(x.familias||[]),...regional].filter(Boolean);if(!prefixQueryMatch(fields,q))return 0;return Math.max(1,...fields.map(f=>fieldRank(f,q)))}
function visualMarca(x){let m=(x.marca||'').trim(),d=(x.dci||'').trim();if(!m&&d)return d+' (genérico)';if(m&&d&&norm(m)===norm(d))return m+' (genérico)';return m||d||'Medicamento'}
function shortPres(x){let p=x.presentaciones||[];return p.length?p.slice(0,2).join(' · '):'Detalle en verificación'}
function buildLists(){let names=[...new Set(allMeds.flatMap(x=>[x.marca,x.dci,...principles(x)]).filter(Boolean))].sort((a,b)=>norm(a).localeCompare(norm(b),'es'));$('#drugList').innerHTML=names.map(x=>`<option value="${esc(x)}">`).join('');let pd=[...new Set((window.VCB_PED_GUIDES||[]).map(x=>x.drug))].sort((a,b)=>norm(a).localeCompare(norm(b),'es'));$('#pedDrugList').innerHTML=pd.map(x=>`<option value="${esc(x)}">`).join('')}
function recordSearch(q){q=q.trim();if(q.length<2)return;let key='vcu_freq090',o=JSON.parse(localStorage.getItem(key)||'{}'),n=norm(q);let found=Object.keys(o).find(k=>norm(k)===n);if(found)o[found]++;else o[q]=1;localStorage.setItem(key,JSON.stringify(o));renderFrequent()}
function renderFrequent(){let o=JSON.parse(localStorage.getItem('vcu_freq090')||'{}'),a=Object.entries(o).filter(x=>x[1]>=3).sort((a,b)=>b[1]-a[1]).slice(0,7);$('#frequentBox').classList.toggle('hidden',!a.length);$('#frequentButtons').innerHTML=a.map(([q])=>`<button class="freq-chip" data-q="${esc(q)}">${esc(q)}</button>`).join('');$$('.freq-chip').forEach(b=>b.onclick=()=>{$('#q').value=b.dataset.q;selectedLab='';recordSearch(b.dataset.q);search()})}
function search(){let q=norm($('#q').value),res=$('#resultados'),home=$('#searchEmpty');if(!q){res.innerHTML='';$('#labFilters').classList.add('hidden');home.classList.remove('hidden');return}home.classList.add('hidden');let ranked=allMeds.map(x=>[x,searchScore(x,q)]).filter(([,score])=>score>0),supRanked=boliviaSupplies().map(x=>[x,supplySearchScore(x,q)]).filter(([,score])=>score>0);let labs=[...new Set(ranked.map(([x])=>x.laboratorio).filter(Boolean))].sort((a,b)=>norm(a).localeCompare(norm(b),'es'));renderLabFilters(labs);if(selectedLab)ranked=ranked.filter(([x])=>norm(x.laboratorio)===norm(selectedLab));ranked.sort((a,b)=>b[1]-a[1]||norm(visualMarca(a[0])).localeCompare(norm(visualMarca(b[0])),'es'));supRanked.sort((a,b)=>b[1]-a[1]||norm(a[0].marca).localeCompare(norm(b[0].marca),'es'));let meds=ranked.map(([x])=>x),sup=supRanked.map(([x])=>x),singles=meds.filter(x=>!isCombined(x)),combos=meds.filter(isCombined);let html=regulatoryQueryNotice(q);if(singles.length)html+=resultSection('Medicamentos solos',singles,false);if(combos.length)html+=`<div class="association-panel">${resultSection('Asociaciones / medicamentos compuestos',combos,true)}</div>`;if(sup.length)html+=supplySection(sup);if(!html)html='<div class="empty-card"><b>No se encontró en la base local.</b><p>La base continúa ampliándose. Pruebe por marca, principio activo, laboratorio o insumo.</p></div>';res.innerHTML=html;$$('.drug-row[data-id]').forEach(r=>r.onclick=()=>openMedicine(r.dataset.id));$$('.drug-row[data-supply]').forEach(r=>r.onclick=()=>openSupply(r.dataset.supply))}
function renderLabFilters(labs){let el=$('#labFilters');if(labs.length<2){el.classList.add('hidden');el.innerHTML='';return}el.classList.remove('hidden');el.innerHTML=`<button class="lab-chip ${!selectedLab?'active':''}" data-lab="">Todos</button>`+labs.map(l=>`<button class="lab-chip ${norm(l)===norm(selectedLab)?'active':''}" data-lab="${esc(l)}">${esc(l)}</button>`).join('');$$('.lab-chip').forEach(b=>b.onclick=()=>{selectedLab=b.dataset.lab;search()})}
function resultSection(title,rows,assoc){return `<div class="result-section"><div class="section-title"><h3>${title}</h3><span>${rows.length}</span></div><div class="drug-list">${rows.slice(0,250).map(x=>drugRow(x,assoc)).join('')}</div></div>`}function drugRow(x,assoc){return `<div class="drug-row ${assoc?'assoc':''}" data-id="${esc(x.id)}"><div><div class="marca">${esc(visualMarca(x))}${assoc?'<span class="combined-badge">COMBINADO</span>':''}</div><div class="dci">${esc(x.dci||principles(x).join(' + ')||'Detalle en verificación')}</div></div><div class="dci">${esc(principles(x).join(' + ')||'Detalle en verificación')}</div><div class="presentation">${esc(shortPres(x))}</div><div class="lab">${esc(x.laboratorio||'Laboratorio por confirmar')}</div><div class="arrow">›</div></div>`}
function supplySection(rows){return `<div class="result-section"><div class="section-title"><h3>Insumos, implantes y proveedores · Bolivia</h3><span>${rows.length}</span></div><div class="drug-list">${rows.map(x=>`<div class="drug-row" data-supply="${esc(x.id)}"><div><div class="marca">${esc(x.marca)}<span class="supply-badge ${x.tipo_registro==='proveedor'?'provider-badge':''}">${x.tipo_registro==='proveedor'?'DIRECTORIO':(x.grupo_catalogo==='implante'?'IMPLANTE':(x.grupo_catalogo==='servicio'?'SOPORTE':'BOLIVIA'))}</span></div><div class="dci">${esc(x.nombre)}</div></div><div class="dci">${esc(x.categoria)}</div><div class="presentation">${esc((x.presentaciones||[]).slice(0,2).join(' · ')||'Detalle en verificación')}</div><div class="lab">${esc(x.proveedor_bolivia||x.fabricante||'Proveedor Bolivia')}</div><div class="arrow">›</div></div>`).join('')}</div></div>`}
function ingredientKey(s){let n=norm(s);if(n.includes('diclofenaco'))return'diclofenaco';if(n.includes('paracetamol')||n.includes('acetaminofen'))return'paracetamol';if(n.includes('metamizol')||n.includes('dipirona'))return'metamizol';if(n.includes('valproato')||n.includes('acido valproico'))return'valproato';return n.replace(/\b(clorhidrato|hidrocloruro|sodico|sodica|potasico|potasica|diclorhidrato|acetato|succinato)\b/g,'').replace(/\s+/g,' ').trim()}
function ingredientKeys(x){return[...new Set(principles(x).flatMap(p=>p.split(/\s*(?:\+|;)\s*/)).map(ingredientKey).filter(Boolean))]}
function openMedicine(id){let x=allMeds.find(z=>z.id===id);if(!x)return;recordSearch(x.marca||x.dci);let prs=(x.presentaciones||[]).filter(p=>norm(p)!=='detalle en verificacion').map(p=>`<li>${esc(p)}</li>`).join('')||'<li>Detalle en verificación</li>';let baseKeys=ingredientKeys(x),rel=allMeds.filter(z=>z.id!==x.id&&isCombined(z)&&ingredientKeys(z).some(k=>baseKeys.includes(k))).sort((a,b)=>norm(a.marca).localeCompare(norm(b.marca),'es')).slice(0,10);let combo=isCombined(x)?`<div class="modal-section"><h4>Componentes de la asociación</h4><div class="components">${esc(principles(x).join(' + '))}</div></div>`:'';let related=rel.length?`<div class="modal-section"><h4>Asociaciones relacionadas</h4><div class="related-grid">${rel.map(r=>`<button class="related-btn" data-related="${esc(r.id)}"><b>${esc(visualMarca(r))}</b><br><small>${esc(principles(r).join(' + '))}</small></button>`).join('')}</div></div>`:'';let verify=x.detalle_completo===false?'<div class="warning-banner"><b>Detalle en verificación:</b> la marca está registrada en la base, pero faltan datos confirmados de composición o presentación.</div>':'';$('#modalContent').innerHTML=`<h2 class="modal-title">${esc(visualMarca(x))}</h2><div class="modal-sub">${esc(x.dci||principles(x).join(' + ')||'Detalle en verificación')}</div>${verify}${medicineRegulatoryAlerts(x)}${combo}<div class="modal-section"><h4>Presentaciones</h4><ul class="pres-list">${prs}</ul></div><div class="modal-section"><h4>Laboratorio</h4><b>${esc(x.laboratorio||'Detalle en verificación')}</b></div>${evidenceBlockMedicine(x)}${related}`;$('#medModal').classList.remove('hidden');document.body.classList.add('modal-open');$$('[data-related]').forEach(b=>b.onclick=()=>openMedicine(b.dataset.related))}
function contactButtons(x){let a=[];(x.telefonos||[]).forEach(t=>{let href='tel:'+t.replace(/[^+\d]/g,'');a.push(`<a class="contact-btn" href="${esc(href)}">☎ ${esc(t)}</a>`)});[x.whatsapp,...(x.whatsapp_adicionales||[])].filter(Boolean).forEach((n,i)=>{let w=n.replace(/\D/g,'');a.push(`<a class="contact-btn whatsapp" href="https://wa.me/${esc(w)}" target="_blank" rel="noopener">WhatsApp${i?` ${i+1}`:''}</a>`)});if(x.email)a.push(`<a class="contact-btn" href="mailto:${esc(x.email)}">✉ ${esc(x.email)}</a>`);return a.length?`<div class="contact-actions">${a.join('')}</div>`:''}
function regionalContactsHtml(x){let rows=x.contactos_departamento||[];if(!rows.length)return'';return `<div class="regional-contacts"><h4>Contactos por departamento</h4>${rows.map(c=>{let btns=(c.telefonos||[]).map(t=>`<a class="regional-phone" href="tel:${esc(t.replace(/[^+\d]/g,''))}">☎ ${esc(t)}</a>`).join('');let was=[c.whatsapp,...(c.whatsapp_adicionales||[])].filter(Boolean).map((n,i)=>`<a class="regional-phone whatsapp" href="https://wa.me/${esc(n.replace(/\D/g,''))}" target="_blank" rel="noopener">WhatsApp${i?` ${i+1}`:''}</a>`).join('');return `<details class="regional-contact"><summary><b>${esc(c.departamento||c.ciudad||'Bolivia')}</b>${c.ciudad&&c.ciudad!==c.departamento?` · ${esc(c.ciudad)}`:''}</summary>${c.contacto?`<div class="regional-address"><b>Contacto:</b> ${esc(c.contacto)}</div>`:''}${c.direccion?`<div class="regional-address">${esc(c.direccion)}</div>`:''}<div class="regional-phone-grid">${btns}${was}</div></details>`}).join('')}</div>`}
function openSupply(id){let x=[...boliviaSupplyProducts(),...boliviaProviders()].find(z=>z.id===id);if(!x)return;let isProvider=x.tipo_registro==='proveedor',isService=(x.grupo_catalogo==='servicio'||x.tipo_registro==='servicio');let linked=x.proveedor_id?boliviaProviders().find(p=>p.id===x.proveedor_id):null;let px=linked||x;let provider=x.proveedor_bolivia?`<div class="modal-section bolivia-provider"><h4>${isProvider?'Empresa / cobertura en Bolivia':'Proveedor en Bolivia'}</h4><b>${esc(x.proveedor_bolivia)}</b>${px.contacto?`<div class="provider-address"><b>Contacto:</b> ${esc(px.contacto)}</div>`:''}${px.direccion?`<div class="provider-address">${esc(px.direccion)}</div>`:''}${contactButtons(px)}${regionalContactsHtml(px)}</div>`:'';let state=x.estado_bolivia?`<div class="verification-note">${esc(x.estado_bolivia)}</div>`:'';$('#modalContent').innerHTML=`<div class="bolivia-only-badge ${isProvider?'provider-only-badge':''}">${isProvider?(x.verificacion_bolivia===true?'PROVEEDOR BOLIVIA':'PROVEEDOR REPORTADO · PENDIENTE'):(isService?'SOPORTE / SERVICIO BOLIVIA':'VERIFICADO EN BOLIVIA')}</div><h2 class="modal-title">${esc(x.marca)}</h2><div class="modal-sub">${esc(x.nombre)}</div><div class="modal-section"><h4>${isProvider?'Áreas / productos':(isService?'Tipo de soporte / servicio':'Tipo de insumo / implante')}</h4><div class="supply-detail">${esc(x.categoria)}</div>${x.implant_family?`<div class="implant-family-line"><b>Familia:</b> ${esc(x.implant_family)}</div>`:''}</div><div class="modal-section"><h4>${isProvider?'Portafolio declarado':(isService?'Alcance publicado / por confirmar':'Presentaciones / medidas')}</h4><ul class="pres-list">${(x.presentaciones||[]).map(p=>`<li>${esc(p)}</li>`).join('')||'<li>Detalle en verificación</li>'}</ul></div><div class="modal-section"><h4>${isProvider?'Representaciones / líneas':'Fabricante / línea'}</h4><b>${esc(x.fabricante||'Detalle en verificación')}</b></div>${provider}${evidenceBlockSupply(x)}${state}`;$('#medModal').classList.remove('hidden');document.body.classList.add('modal-open')}
function closeModal(){$('#medModal').classList.add('hidden');document.body.classList.remove('modal-open')}

