function categoryText(x){return norm([x.marca,x.dci,principles(x).join(' '),(x.aliases||[]).join(' '),(x.presentaciones||[]).join(' '),x.accion_terapeutica||''].join(' '))}
function matchesTerms(x,terms){let s=categoryText(x);return terms.some(v=>s.includes(norm(v)))}
function procedureCatalogItems(){let terms=['lidocaina','bupivacaina','betametasona','clorhexidina'];return allMeds.filter(x=>{let s=searchable(x);if(!terms.some(t=>s.includes(t)))return false;return /ampolla|ampoule|vial|inyect|frasco ampolla|pesad|solucion/.test(s)}).sort((a,b)=>norm(visualMarca(a)).localeCompare(norm(visualMarca(b)),'es'))}
