 if(tab==='proveedores'){let rows=boliviaProviders().sort((a,b)=>norm(a.marca).localeCompare(norm(b.marca),'es'));el.innerHTML=`<div class="provider-directory-head"><b>Directorio de proveedores Bolivia · verificados y pendientes identificados</b><span>Los teléfonos se muestran por departamento cuando existe una fuente empresarial pública.</span></div><div class="drug-list">${rows.map(x=>`<div class="drug-row" data-supply="${esc(x.id)}"><div><div class="marca">${esc(x.marca)}<span class="supply-badge provider-badge">${x.verificacion_bolivia===true?'DIRECTORIO':'PENDIENTE'}</span></div><div class="dci">${esc(x.nombre)}</div></div><div class="dci">${esc((x.familias||[]).slice(0,4).join(' · '))}</div><div class="presentation">${esc((x.presentaciones||[]).slice(0,3).join(' · '))}</div><div class="lab">${esc((x.contactos_departamento||[]).map(c=>c.departamento).filter(Boolean).join(' · ')||'Bolivia')}</div><div class="arrow">›</div></div>`).join('')}</div>`;$$('.drug-row[data-supply]').forEach(r=>r.onclick=()=>openSupply(r.dataset.supply));return}
