// Pediatric calculator
function ageMonths(){let v=Number($('#pedAge').value);if(!(v>=0))return null;return $('#pedAgeUnit').value==='years'?v*12:v}function pedDrugDef(){let n=norm($('#pedDrug').value);return(window.VCB_PED_GUIDES||[]).find(d=>norm(d.drug)===n||(d.aliases||[]).some(a=>norm(a)===n))}function eligibleRegimens(d,age,kg){return(d?.regimens||[]).filter(r=>(r.minAgeMonths==null||age>=r.minAgeMonths)&&(r.maxAgeMonths==null||age<=r.maxAgeMonths)&&(r.minWeightKg==null||kg>=r.minWeightKg))}
function refreshPedRegimens(){let d=pedDrugDef(),age=ageMonths(),kg=Number($('#pedKg').value)||0,r=d&&age!=null?eligibleRegimens(d,age,kg):[];$('#pedRegimen').innerHTML=r.length?r.map((x,i)=>`<option value="${i}">${esc(x.label)}</option>`).join(''):'<option value="">No hay esquema automático para estos datos</option>';refreshPedPresentations();renderGuide()}
function parseConcentration(text){let t=text.replace(/,/g,'.'),dropsPerMl=null,mgPerDrop=null,dm=t.match(/(\d+(?:\.\d+)?)\s*gotas?\s*\/\s*mL/i),gd=t.match(/(\d+(?:\.\d+)?)\s*mg\s*(?:por|\/)\s*gota/i);if(dm)dropsPerMl=+dm[1];if(gd)mgPerDrop=+gd[1];let m=t.match(/(\d+(?:\.\d+)?)\s*mg\s*\/\s*(\d+(?:\.\d+)?)\s*mL/i);if(!m)m=t.match(/(\d+(?:\.\d+)?)\s*mg\s*\/\s*mL/i);let out=null;if(m)out={mg:+m[1],ml:m[2]?+m[2]:1,label:text};if(!out){m=t.match(/(\d+(?:\.\d+)?)\s*mg\s+en\s+(\d+(?:\.\d+)?)\s*mL/i);if(m)out={mg:+m[1],ml:+m[2],label:text}}if(!out)return null;if(!dropsPerMl&&mgPerDrop>0){let mgPerMl=out.mg/out.ml;dropsPerMl=mgPerMl/mgPerDrop}out.dropsPerMl=dropsPerMl;return out}
function refreshPedPresentations(){let d=pedDrugDef();if(!d){$('#pedPresentation').innerHTML='<option value="">Elija medicamento</option>';return}let names=[d.drug,...(d.aliases||[])].map(norm),opts=[];allMeds.forEach(x=>{let s=principles(x).map(norm);if(!names.some(n=>s.some(p=>p.includes(n)||n.includes(p))||norm(x.dci).includes(n)))return;(x.presentaciones||[]).forEach(p=>{let c=parseConcentration(p);if(c)opts.push({...c,marca:visualMarca(x),lab:x.laboratorio})})});let seen=new Set();opts=opts.filter(o=>{let k=norm(o.marca+'|'+o.label);if(seen.has(k))return false;seen.add(k);return true}).sort((a,b)=>norm(a.marca).localeCompare(norm(b.marca),'es'));$('#pedPresentation').innerHTML='<option value="">Elija una presentación del catálogo</option>'+opts.map((o,i)=>`<option value="${o.mg}|${o.ml}|${o.dropsPerMl||''}" data-label="${esc(o.label)}">${esc(o.marca)} — ${esc(o.label)}${o.lab?' — '+esc(o.lab):''}</option>`).join('')}
function currentReg(){let d=pedDrugDef(),age=ageMonths(),kg=Number($('#pedKg').value)||0,r=eligibleRegimens(d,age,kg),i=Number($('#pedRegimen').value||0);return r[i]||null}function renderGuide(){let r=currentReg(),g=$('#pedGuide');if(!r){g.classList.add('hidden');return}let dose=r.doseMode==='warning'?'Sin cálculo automático':r.doseMode==='perDay'?`${r.doseMin}${r.doseMax!==r.doseMin?'–'+r.doseMax:''} mg/kg/día`:`${r.doseMin}${r.doseMax!==r.doseMin?'–'+r.doseMax:''} mg/kg/dosis`;let mx=[];if(r.maxDoseMg)mx.push(`máx. ${r.maxDoseMg} mg/dosis`);if(r.maxDailyMgKg)mx.push(`máx. ${r.maxDailyMgKg} mg/kg/día`);if(r.maxDailyMg)mx.push(`máx. ${r.maxDailyMg} mg/día`);g.innerHTML=`<strong>${esc(r.label)}</strong><div class="guide-meta"><span><b>Dosis guía:</b> ${esc(dose)}</span><span><b>Frecuencia:</b> ${esc(r.interval||'según pauta')}</span>${mx.length?`<span><b>Límite:</b> ${esc(mx.join(' · '))}</span>`:''}</div>${r.target?`<div class="guide-meta"><span><b>Titulación/objetivo:</b> ${esc(r.target)}</span></div>`:''}${r.note?`<p>${esc(r.note)}</p>`:''}<small>Fuente: ${esc(r.source)}</small>`;g.classList.remove('hidden')}
function chosenConc(){let v=$('#pedPresentation').value;if(v){let parts=v.split('|'),mg=Number(parts[0]),ml=Number(parts[1]),dropsPerMl=Number(parts[2]);if(mg>0&&ml>0)return{mg,ml,dropsPerMl:dropsPerMl>0?dropsPerMl:null,label:$('#pedPresentation').selectedOptions[0]?.textContent||''}}let mg=Number($('#pedManualMg').value),ml=Number($('#pedManualMl').value);return mg>0&&ml>0?{mg,ml,dropsPerMl:null,label:`${mg} mg en ${ml} mL`}:null}function fmt(n){return(Math.round(n*100)/100).toLocaleString('es-BO',{maximumFractionDigits:2})}
function calcPed(){let d=pedDrugDef(),r=currentReg(),kg=Number($('#pedKg').value),age=ageMonths();if(!d){toast('Seleccione un medicamento de la biblioteca pediátrica');return}if(age==null||!(kg>0)){toast('Ingrese edad y peso');return}if(!r){toast('No hay esquema automático para esta edad/peso');return}if(r.doseMode==='warning'){$('#pedResult').innerHTML=`<div class="big">No calcular automáticamente</div><div>${esc(r.note||'Revise la guía antes de prescribir.')}</div><div class="limit">Fuente: ${esc(r.source)}</div>`;$('#pedResult').classList.remove('hidden');return}let lo,hi,dailyLo,dailyHi;if(r.doseMode==='perDay'){dailyLo=kg*r.doseMin;dailyHi=kg*r.doseMax;if(r.maxDailyMgKg){dailyLo=Math.min(dailyLo,kg*r.maxDailyMgKg);dailyHi=Math.min(dailyHi,kg*r.maxDailyMgKg)}if(r.maxDailyMg){dailyLo=Math.min(dailyLo,r.maxDailyMg);dailyHi=Math.min(dailyHi,r.maxDailyMg)}let f=r.frequency||1;lo=dailyLo/f;hi=dailyHi/f}else{lo=kg*r.doseMin;hi=kg*r.doseMax;if(r.maxDoseMg){lo=Math.min(lo,r.maxDoseMg);hi=Math.min(hi,r.maxDoseMg)}dailyLo=lo*(r.frequency||1);dailyHi=hi*(r.frequency||1);if(r.maxDailyMgKg){dailyLo=Math.min(dailyLo,kg*r.maxDailyMgKg);dailyHi=Math.min(dailyHi,kg*r.maxDailyMgKg)}if(r.maxDailyMg){dailyLo=Math.min(dailyLo,r.maxDailyMg);dailyHi=Math.min(dailyHi,r.maxDailyMg)}}let c=chosenConc(),volLo=null,volHi=null;if(c){volLo=lo*c.ml/c.mg;volHi=hi*c.ml/c.mg}let dose=Math.abs(hi-lo)<.001?`${fmt(lo)} mg por dosis`:`${fmt(lo)}–${fmt(hi)} mg por dosis`;let vol=volLo!=null?(Math.abs(volHi-volLo)<.001?`${fmt(volLo)} mL por dosis`:`${fmt(volLo)}–${fmt(volHi)} mL por dosis`):'';let drops='';let dpm=c?.dropsPerMl;if(volLo!=null&&dpm>0){let a=volLo*dpm,b=volHi*dpm;drops=Math.abs(a-b)<.01?`${fmt(a)} gotas por dosis`:`${fmt(a)}–${fmt(b)} gotas por dosis`}let maxTxt=[];if(r.maxDoseMg)maxTxt.push(`Máximo por dosis: ${r.maxDoseMg} mg`);if(r.maxDailyMgKg)maxTxt.push(`Máximo diario: ${r.maxDailyMgKg} mg/kg/día`);if(r.maxDailyMg)maxTxt.push(`Máximo absoluto diario: ${r.maxDailyMg} mg`);$('#pedResult').innerHTML=`<div>${esc(d.drug)} · ${esc(r.label)}</div><div class="big">${esc(drops||vol||dose)}</div>${drops?`<div class="sub">${esc(vol)} · ${esc(dose)}</div>`:vol?`<div class="sub">${esc(dose)}</div>`:''}<div class="sub">${esc(r.interval||'')}</div>${c?`<div class="sub">Con: ${esc(c.label)}</div>`:'<div class="sub">Sin conversión a mL: elija o introduzca una concentración.</div>'}${maxTxt.length?`<div class="limit">${esc(maxTxt.join(' · '))}</div>`:''}<div class="limit">Fuente: ${esc(r.source)} · Verifique indicación, edad, función renal/hepática y ficha del producto.</div>`;$('#pedResult').classList.remove('hidden')}
function clearPed(){['pedDrug','pedAge','pedKg','pedManualMg','pedManualMl'].forEach(id=>$('#'+id).value='');$('#pedRegimen').innerHTML='<option value="">Primero elija medicamento y edad</option>';$('#pedPresentation').innerHTML='<option value="">Elija una presentación del catálogo</option>';$('#pedGuide').classList.add('hidden');$('#pedResult').classList.add('hidden')}

// Interaction engine from v0.8
function splitPrinciples(v){return(Array.isArray(v)?v:[v]).flatMap(s=>(s||'').toString().split(/\s*\+\s*|\s*;\s*/)).map(s=>s.trim()).filter(Boolean)}
function canonicalIngredient(s){let n=norm(s);if(n.includes('diclofenaco'))return'Diclofenaco';if(n.includes('paracetamol')||n.includes('acetaminofen'))return'Paracetamol';if(n.includes('metamizol')||n.includes('dipirona'))return'Metamizol';if(n.includes('valproato')||n.includes('acido valproico'))return'Valproato';return s.trim()}
function resolveInput(v){let n=norm(v);if(!n)return{label:v,ingredients:[],matches:[]};let exact=allMeds.filter(x=>norm(x.marca)===n||norm(x.dci)===n||principles(x).some(p=>norm(p)===n)),ms=exact.length?exact:allMeds.map(x=>[x,searchScore(x,n)]).filter(([,score])=>score>0).sort((a,b)=>b[1]-a[1]).slice(0,50).map(([x])=>x),ing=[...new Set(ms.flatMap(x=>splitPrinciples(principles(x))).filter(Boolean).map(canonicalIngredient))];if(!ing.length)ing=splitPrinciples(v).map(canonicalIngredient);return{label:v,ingredients:ing,matches:ms}}
function ruleVariants(s){return(s||'').split('/').map(x=>norm(x)).filter(Boolean)}
function ruleTermMatches(ingredient,ruleTerm){let n=norm(ingredient);return ruleVariants(ruleTerm).some(v=>n===v||n.includes(v)||v.includes(n))}
function checkPair(a,b){return(window.VCB_INTERACTIONS||[]).filter(x=>(ruleTermMatches(a,x.a)&&ruleTermMatches(b,x.b))||(ruleTermMatches(a,x.b)&&ruleTermMatches(b,x.a)))}
let interactionRows=0;
function addInteractionRow(v=''){if(interactionRows>=10)return;interactionRows++;let row=document.createElement('div');row.className='interaction-row';row.innerHTML=`<span class="interaction-num">${interactionRows}</span><input class="int-med" list="drugList" placeholder="Medicamento o marca comercial" value="${esc(v)}"><button class="remove-int" aria-label="Quitar medicamento">×</button>`;$('#interactionInputs').appendChild(row);row.querySelector('.remove-int').onclick=()=>{row.remove();renumberInteractionRows()}}
function renumberInteractionRows(){let rows=$$('.interaction-row');interactionRows=rows.length;rows.forEach((r,i)=>r.querySelector('.interaction-num').textContent=i+1);while(interactionRows<2)addInteractionRow()}
function alertBox(level,title,text,conducta='',fuente=''){let cls=norm(level).includes('contra')?'contra':norm(level).includes('alta')?'high':'';return`<div class="interaction ${cls}"><b>${esc(title)} · ${esc(level)}</b><p>${esc(text)}</p>${conducta?`<p><b>Orientación:</b> ${esc(conducta)}</p>`:''}${fuente?`<div class="rule-source"><b>Fuente:</b> ${esc(fuente)}</div>`:''}</div>`}
function renderInteractionsMulti(){let vals=$$('.int-med').map(x=>x.value.trim()).filter(Boolean),el=$('#interactionList');if(vals.length<2){toast('Agregue al menos dos medicamentos');return}let resolved=vals.map(resolveInput),items=[],seen=new Set(),info='<div class="resolved-list">'+resolved.map(r=>`<div><b>${esc(r.label)}</b><span>${esc(r.ingredients.join(' + ')||'composición no resuelta')}</span></div>`).join('')+'</div>';for(let i=0;i<resolved.length;i++)for(let j=i+1;j<resolved.length;j++){let dup=resolved[i].ingredients.filter(a=>resolved[j].ingredients.some(b=>norm(a)===norm(b)));if(dup.length){let k='dup:'+dup.map(norm).sort().join('|');if(!seen.has(k)){seen.add(k);items.push(alertBox('Alta','Duplicidad de principio activo',`${resolved[i].label} y ${resolved[j].label} comparten: ${[...new Set(dup)].join(' + ')}. Revise la dosis total acumulada.`))}}}for(let i=0;i<resolved.length;i++)for(let j=i+1;j<resolved.length;j++)for(let a of resolved[i].ingredients)for(let b of resolved[j].ingredients)checkPair(a,b).forEach(x=>{let k='rule:'+norm(x.a)+'|'+norm(x.b);if(!seen.has(k)){seen.add(k);items.push(alertBox(x.nivel,`${x.a} + ${x.b}`,x.resumen,x.conducta,x.fuente||''))}});let all=resolved.flatMap(r=>r.ingredients.map(canonicalIngredient)),ns=['Diclofenaco','Ibuprofeno','Ketorolaco','Naproxeno','Ketoprofeno','Meloxicam','Piroxicam','Celecoxib','Etoricoxib','Dexketoprofeno'],nsaids=[...new Set(all.filter(x=>ns.some(n=>norm(x)===norm(n))))];if(nsaids.length>=2)items.push(alertBox('Alta','Duplicidad de AINE',`Se detectan ${nsaids.join(' + ')}. La asociación aumenta riesgo gastrointestinal, renal y hemorrágico.`,'Evitar salvo indicación excepcional y supervisada.'));let ops=[...new Set(all.filter(x=>['Tramadol','Morfina','Codeína','Tapentadol','Fentanilo','Oxicodona','Buprenorfina','Metadona'].some(o=>norm(x)===norm(o))))],bzs=[...new Set(all.filter(x=>['Clonazepam','Diazepam','Alprazolam','Lorazepam','Midazolam','Bromazepam','Clotiazepam'].some(o=>norm(x)===norm(o))))];if(ops.length&&bzs.length)items.push(alertBox('Alta','Opioide + benzodiacepina',`${ops.join(', ')} con ${bzs.join(', ')} puede producir sedación intensa y depresión respiratoria.`,'Evitar cuando sea posible; si se usa, minimizar exposición y vigilar estrechamente.'));let gabs=[...new Set(all.filter(x=>['Pregabalina','Gabapentina'].some(o=>norm(x)===norm(o))))];if(ops.length&&gabs.length)items.push(alertBox('Moderada/Alta','Opioide + gabapentinoide',`${ops.join(', ')} con ${gabs.join(', ')} puede aumentar sedación y depresión respiratoria.`,'Valorar necesidad y factores de riesgo.'));let tram=all.some(x=>norm(x)==='tramadol'),sero=['Sertralina','Fluoxetina','Paroxetina','Citalopram','Escitalopram','Venlafaxina','Duloxetina','Amitriptilina','Clomipramina','Mirtazapina','Trazodona','Linezolid'],ss=[...new Set(all.filter(x=>sero.some(o=>norm(x)===norm(o))))];if(tram&&ss.length)items.push(alertBox('Moderada/Alta','Tramadol + serotoninérgico',`Con ${ss.join(', ')} aumenta el riesgo de síndrome serotoninérgico y convulsiones.`,'Valorar alternativa y vigilar.'));if(!items.length)items.push('<div class="warning-banner">No se encontró una interacción registrada en la base local.</div>');el.innerHTML=info+items.join('')+'<div class="warning-banner interaction-disclaimer"><b>Advertencia:</b> No encontrar una interacción no confirma que la combinación sea segura.</div>'}
function clearInteractions(){$('#interactionInputs').innerHTML='';interactionRows=0;addInteractionRow();addInteractionRow();$('#interactionList').innerHTML=''}

// Sincronización versionada y silenciosa: solo agrega/actualiza; nunca borra fichas locales.
function updateSyncUi(text){let el=$('#syncStatus');if(el)el.textContent=text}
function validCatalog(rows){if(!Array.isArray(rows)||!rows.length)return false;let ids=new Set();for(let x of rows){if(!x||!x.id||ids.has(x.id))return false;ids.add(x.id)}return true}
async function fetchWithTimeout(url,ms=8000){let c=new AbortController(),t=setTimeout(()=>c.abort(),ms);try{return await fetch(url,{cache:'no-store',signal:c.signal})}finally{clearTimeout(t)}}
async function maybeSyncCatalog(force=false){let cfg=window.VCB_CONFIG||{},url=cfg.updateManifestUrl;if(!url||!navigator.onLine){updateSyncUi(`Catálogo Bolivia: ${allMeds.length} medicamentos · ${boliviaImplants().length} implantes · ${boliviaNonImplantSupplies().length} insumos/equipos · ${boliviaServices().length} soporte/alquiler · ${boliviaProviders().length} proveedores · sin conexión o sin origen remoto configurado.`);return}let key='vcb_last_sync_check',last=Number(localStorage.getItem(key)||0),interval=Number(cfg.syncIntervalMs||86400000);if(!force&&Date.now()-last<interval)return;localStorage.setItem(key,String(Date.now()));try{let mr=await fetchWithTimeout(url);if(!mr.ok)throw new Error('manifest '+mr.status);let meta=await mr.json(),current=localStorage.getItem('vcb_catalog_version')||cfg.bundledCatalogVersion||'0.19.0';if(!meta.version||meta.version===current){updateSyncUi(`Catálogo ${current} · ${allMeds.length} medicamentos Bolivia · ${boliviaImplants().length} implantes · ${boliviaNonImplantSupplies().length} insumos/equipos · ${boliviaServices().length} soporte/alquiler.`);return}let catalogUrl=new URL(meta.catalogUrl||'./catalogo_medicamentos_v0.19.0.json',mr.url).href,cr=await fetchWithTimeout(catalogUrl,15000);if(!cr.ok)throw new Error('catalog '+cr.status);let incoming=await cr.json();if(!validCatalog(incoming))throw new Error('catálogo inválido');let min=Math.max(allMeds.length,Number(cfg.minimumCatalogCount||0));if(incoming.length<min)throw new Error(`catálogo remoto menor (${incoming.length}<${min})`);await putMany(incoming);allMeds=boliviaMeds(await getAll());sortCatalog();buildLists();search();localStorage.setItem('vcb_catalog_version',meta.version);updateSyncUi(`Catálogo ${meta.version} · ${allMeds.length} medicamentos Bolivia · ${boliviaImplants().length} implantes · ${boliviaNonImplantSupplies().length} insumos/equipos · ${boliviaServices().length} soporte/alquiler · sincronizado.`)}catch(e){console.warn('Sincronización silenciosa no aplicada:',e);updateSyncUi(`Catálogo Bolivia: ${allMeds.length} medicamentos · ${boliviaImplants().length} implantes · ${boliviaNonImplantSupplies().length} insumos/equipos · ${boliviaServices().length} soporte/alquiler · ${boliviaProviders().length} proveedores · se mantiene la copia offline.`)}}
let deferredInstallPrompt=null;
function wireInstallPrompt(){window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;let b=$('#btnInstall');if(b)b.classList.remove('hidden')});let b=$('#btnInstall');if(b)b.onclick=async()=>{if(!deferredInstallPrompt)return;deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;b.classList.add('hidden')}}

function switchPanel(id){$$('.panel').forEach(x=>x.classList.toggle('active',x.id===id));$$('.navbtn').forEach(x=>x.classList.toggle('active',x.dataset.panel===id));if(id==='categorias')renderCategories(currentCategoryTab)}
function wire(){window.addEventListener('online',()=>{$('#netBadge span').textContent='Con conexión · base local disponible';maybeSyncCatalog().catch(console.warn)});window.addEventListener('offline',()=>$('#netBadge span').textContent='Sin conexión · base local disponible');$$('.navbtn').forEach(b=>b.onclick=()=>switchPanel(b.dataset.panel));$$('[data-go]').forEach(b=>b.onclick=()=>switchPanel(b.dataset.go));$('#q').oninput=()=>{selectedLab='';search()};$('#q').addEventListener('keydown',e=>{if(e.key==='Enter'){recordSearch($('#q').value);search()}});$('#btnClear').onclick=()=>{$('#q').value='';selectedLab='';search();$('#q').focus()};$$('[data-close-modal]').forEach(x=>x.onclick=closeModal);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});$$('.cat-tab').forEach(b=>b.onclick=()=>renderCategories(b.dataset.cat));['pedDrug','pedAge','pedKg'].forEach(id=>$('#'+id).addEventListener('input',refreshPedRegimens));$('#pedAgeUnit').onchange=refreshPedRegimens;$('#pedRegimen').onchange=()=>{renderGuide();refreshPedPresentations()};$('#btnPed').onclick=calcPed;$('#btnPedClear').onclick=clearPed;$('#btnAddInteraction').onclick=()=>addInteractionRow();$('#btnInteraccion').onclick=renderInteractionsMulti;$('#btnClearInteractions').onclick=clearInteractions;wireInstallPrompt();clearInteractions()}
window.addEventListener('load',async()=>{wire();try{await initData()}catch(e){console.error(e);toast('No se pudo iniciar la base local')}if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(e=>console.warn('Service worker:',e))});
